// n8n Code node "Clean & validate lead" (Run Once for All Items).
// Normalises a raw form/ad lead into HubSpot-ready fields and flags bad data.
// Input: webhook items ({ body: {...} }). Output: { valid, errors, warnings, lead }.

const FREE_EMAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.co.uk', 'hotmail.com', 'outlook.com', 'live.com',
  'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com', 'mail.com', 'yandex.com',
]);
const COUNTRIES = {
  us: 'United States', usa: 'United States', 'united states': 'United States', 'united states of america': 'United States',
  uk: 'United Kingdom', gb: 'United Kingdom', 'great britain': 'United Kingdom', england: 'United Kingdom',
  'united kingdom': 'United Kingdom', ca: 'Canada', canada: 'Canada', au: 'Australia', australia: 'Australia',
  de: 'Germany', germany: 'Germany', fr: 'France', france: 'France', ug: 'Uganda', uganda: 'Uganda',
  ke: 'Kenya', kenya: 'Kenya', ng: 'Nigeria', nigeria: 'Nigeria', in: 'India', india: 'India',
};
const EMAIL = /^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i;

const text = (value) => (value === undefined || value === null ? '' : String(value).replace(/\s+/g, ' ').trim());
const titleCase = (value) => value.toLowerCase().replace(/(^|[\s'’-])(\p{L})/gu, (_, sep, ch) => sep + ch.toUpperCase());

function normalisePhone(raw, country, warnings) {
  const value = text(raw);
  if (!value) return '';
  const digits = value.replace(/\D/g, '');
  if (value.startsWith('+') && digits.length >= 8 && digits.length <= 15) return `+${digits}`;
  if (value.startsWith('00') && digits.length >= 10) return `+${digits.slice(2)}`;
  if (country === 'United States' || country === 'Canada') {
    if (digits.length === 10) return `+1${digits}`;
    if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
  }
  warnings.push(`phone "${value}" kept as-is: add a country code to standardise it`);
  return value;
}

function normaliseWebsite(raw) {
  const value = text(raw).toLowerCase();
  return value.replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/+$/, '');
}

const results = [];
for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  const errors = [];
  const warnings = [];

  const email = text(body.email).toLowerCase();
  if (!email) errors.push('email is required');
  else if (!EMAIL.test(email)) errors.push(`email "${email}" is not a valid address`);

  let first = text(body.first_name ?? body.firstname ?? body.firstName);
  let last = text(body.last_name ?? body.lastname ?? body.lastName);
  const full = text(body.name ?? body.full_name ?? body.fullName);
  if (!first && full) {
    const parts = full.split(' ');
    first = parts.shift();
    last = last || parts.join(' ');
  }
  if (!first) warnings.push('no first name supplied');

  const rawCountry = text(body.country);
  const country = COUNTRIES[rawCountry.toLowerCase()] ?? (rawCountry ? titleCase(rawCountry) : '');
  const utm = body.utm ?? {};
  const domain = email.includes('@') ? email.split('@')[1] : '';

  const lead = {
    email,
    firstname: first ? titleCase(first) : '',
    lastname: last ? titleCase(last) : '',
    phone: normalisePhone(body.phone, country, warnings),
    company: text(body.company),
    jobtitle: text(body.job_title ?? body.jobtitle ?? body.title),
    website: normaliseWebsite(body.website) || (domain && !FREE_EMAIL_DOMAINS.has(domain) ? domain : ''),
    country,
    employees: Number.parseInt(text(body.employees ?? body.company_size).replace(/[^\d]/g, ''), 10) || null,
    budget: Number.parseInt(text(body.budget).replace(/[^\d]/g, ''), 10) || null,
    form: text(body.form ?? body.form_type).toLowerCase() || 'unknown',
    message: text(body.message),
    utm_source: text(body.utm_source ?? utm.source).toLowerCase(),
    utm_medium: text(body.utm_medium ?? utm.medium).toLowerCase(),
    utm_campaign: text(body.utm_campaign ?? utm.campaign).toLowerCase(),
    marketing_consent: body.marketing_consent === true || ['yes', 'true', '1', 'on'].includes(text(body.marketing_consent).toLowerCase()),
    email_domain: domain,
    free_email: FREE_EMAIL_DOMAINS.has(domain),
  };

  results.push({ json: { valid: errors.length === 0, errors, warnings, lead, received_at: new Date().toISOString() } });
}
return results;

// n8n Code node "Score lead" (Run Once for All Items).
// Transparent rule-based scoring: every point comes with a reason, so sales
// can see why a lead was routed the way it was. Thresholds live in Config.

const config = $('Config').first().json;

function score(lead) {
  const reasons = [];
  let points = 0;
  const add = (value, why) => {
    points += value;
    reasons.push(`+${value} ${why}`);
  };

  if (lead.form === 'demo_request' || lead.form === 'demo') add(25, 'asked for a demo');
  else if (lead.form === 'contact_sales') add(20, 'contacted sales');
  if (!lead.free_email && lead.email_domain) add(20, 'business email');

  const title = lead.jobtitle.toLowerCase();
  if (/\b(ceo|cmo|cto|coo|cfo|chief|founder|co-founder|owner|president|vp|vice president|head|director)\b/.test(title)) {
    add(30, `senior title (${lead.jobtitle})`);
  } else if (/\b(manager|lead|principal)\b/.test(title)) {
    add(15, `manager-level title (${lead.jobtitle})`);
  }

  if (lead.employees >= 200) add(25, `${lead.employees} employees`);
  else if (lead.employees >= 50) add(15, `${lead.employees} employees`);
  if (lead.budget >= 5000) add(20, `budget ${lead.budget}`);
  if (['referral', 'partner'].includes(lead.utm_medium)) add(10, `${lead.utm_medium} traffic`);
  if (lead.message.length >= 40) add(5, 'wrote a detailed message');

  points = Math.min(points, 100);
  const tier = points >= config.hotScore ? 'hot' : points >= config.warmScore ? 'warm' : 'cold';
  return { score: points, tier, reasons };
}

return $input.all().map((item) => ({ json: { ...item.json, ...score(item.json.lead) } }));

// n8n Code node "Merge with existing contact" (Run Once for Each Item).
// Decides create vs update and builds the HubSpot properties so that:
//  - existing good data is never wiped by a blank form field
//  - lifecycle stage only ever moves forward (HubSpot rejects going backwards)
//  - latest attribution (UTMs) and the lead score are always refreshed

const STAGES = ['subscriber', 'lead', 'marketingqualifiedlead', 'salesqualifiedlead', 'opportunity', 'customer', 'evangelist'];
const PROTECTED_IF_SET = ['firstname', 'lastname', 'company', 'jobtitle', 'website', 'country'];

const { lead, score, tier, reasons, warnings } = $('Score lead').item.json;
const existing = $input.item.json.results?.[0] ?? null;
const current = existing?.properties ?? {};

const props = {
  email: lead.email,
  lead_score: String(score),
  lead_tier: tier,
};
for (const key of ['firstname', 'lastname', 'phone', 'company', 'jobtitle', 'website', 'country']) {
  if (!lead[key]) continue; // never overwrite with blanks
  if (existing && PROTECTED_IF_SET.includes(key) && current[key]) continue; // keep what sales already has
  props[key] = lead[key];
}
for (const key of ['utm_source', 'utm_medium', 'utm_campaign']) {
  if (lead[key]) props[`latest_${key}`] = lead[key];
}
if (lead.marketing_consent) props.marketing_consent = 'true';

const wanted = tier === 'hot' ? 'marketingqualifiedlead' : 'lead';
const currentStage = STAGES.indexOf(current.lifecyclestage ?? '');
if (STAGES.indexOf(wanted) > currentStage) props.lifecyclestage = wanted;
if (!existing) props.hs_lead_status = 'NEW';

return {
  json: {
    action: existing ? 'update' : 'create',
    contactId: existing?.id ?? null,
    properties: props,
    score,
    tier,
    reasons,
    warnings,
  },
};

// n8n Code node "Result summary" (Run Once for Each Item).
// Runs after either the create or the update call and builds the response
// returned to the form plus the data used for routing.

const plan = $('Merge with existing contact').item.json;

return {
  json: {
    status: 'ok',
    action: plan.action === 'create' ? 'created' : 'updated',
    contactId: String($input.item.json.id ?? plan.contactId),
    email: plan.properties.email,
    score: plan.score,
    tier: plan.tier,
    reasons: plan.reasons,
    warnings: plan.warnings,
  },
};
